using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Automation;
using System.Windows.Media;
using AgentRadar.Core;
using AgentRadar.Windows.Ui;
namespace AgentRadar.Windows;
public partial class SettingsWindow:Window {
 readonly RadarRuntime _runtime;readonly IPlatformServices? _platform;PromptDraft _draft;readonly StackPanel _content=new(){Margin=new Thickness(18)};readonly TextBlock _validation=new(){TextWrapping=TextWrapping.Wrap,Margin=new Thickness(10,0,10,4)};readonly Button _save;bool _close,_building;string _tab="常规";string _search="";
 public SettingsWindow(RadarRuntime runtime,IPlatformServices? platform=null){InitializeComponent();_runtime=runtime;_platform=platform;_draft=PromptDraft.Capture(runtime.Settings);var tabs=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(12)};foreach(var title in new[]{"常规","监督","提示词","诊断"})tabs.Children.Add(MainWindow.Button(title,()=>{_tab=title;Build();}));DockPanel.SetDock(tabs,Dock.Top);Root.Children.Add(tabs);var bottom=new StackPanel{Margin=new Thickness(8)};bottom.Children.Add(_validation);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};_save=MainWindow.Button("保存",()=>Save());buttons.Children.Add(_save);buttons.Children.Add(MainWindow.Button("放弃草稿",()=>{_draft=PromptDraft.Capture(_runtime.Settings);Build();}));buttons.Children.Add(MainWindow.Button("完成",Close));bottom.Children.Add(buttons);DockPanel.SetDock(bottom,Dock.Bottom);Root.Children.Add(bottom);Root.Children.Add(new ScrollViewer{Content=_content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Closing+=OnClosing;Build();}
 void Build(){_building=true;_content.Children.Clear();switch(_tab){case "常规":General();break;case "监督":Supervision();break;case "提示词":Prompts();break;default:Diagnostics();break;}_building=false;Validate();}
 void Heading(string t,string? body=null){_content.Children.Add(new TextBlock{Text=t,FontSize=16,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,8,0,8)});if(body!=null)_content.Children.Add(new TextBlock{Text=body,TextWrapping=TextWrapping.Wrap,Foreground=Palette.Brush(Palette.Muted),FontSize=12,Margin=new Thickness(0,0,0,10)});}
 CheckBox Check(string title,bool value,Action<bool> set){var box=new CheckBox{Content=title,IsChecked=value,Margin=new Thickness(0,5,0,5),Foreground=Brushes.White};AutomationProperties.SetName(box,title);box.Checked+=(_,_)=>set(true);box.Unchecked+=(_,_)=>set(false);_content.Children.Add(box);return box;}
 void Field(string title,string value,Action<string> set,bool multiline=false){_content.Children.Add(new TextBlock{Text=title,Margin=new Thickness(0,10,0,4),FontSize=12});var box=new TextBox{Text=value,AcceptsReturn=multiline,TextWrapping=multiline?TextWrapping.Wrap:TextWrapping.NoWrap,MinHeight=multiline?76:28,MaxHeight=multiline?150:28,VerticalScrollBarVisibility=multiline?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled,Padding=new Thickness(6),Background=new SolidColorBrush(Color.FromRgb(36,36,40)),Foreground=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(70,70,74))};AutomationProperties.SetName(box,title);box.TextChanged+=(_,_)=>{if(!_building){set(box.Text);Validate();}};_content.Children.Add(box);}
 void General(){Heading("运行与提醒","按原会话身份核验后操作。所有恢复严格先进先出；原会话响应最多等待 30 秒。未知状态、主动停止和等待确认仅提醒。");Check("暂停监控",_runtime.Settings.Paused,v=>_runtime.UpdateSettings(s=>s.Paused=v));Check("开启自动发送",_runtime.Settings.AutoSend,v=>_runtime.UpdateSettings(s=>s.AutoSend=v));Check("狂暴模式",_runtime.Settings.Mode=="rage",v=>_runtime.UpdateSettings(s=>s.Mode=v?"rage":"collaboration"));Check("显示提醒弹窗",_draft.Popup,v=>{_draft.Popup=v;Validate();});Check("提醒音效",_draft.Sound,v=>{_draft.Sound=v;Validate();});Check("夜间常亮",_runtime.Settings.KeepAwake,v=>{try{_platform?.SetKeepAwake(v);_runtime.UpdateSettings(s=>s.KeepAwake=v);}catch{ProductDialog.Show("夜间常亮","系统未确认常亮请求，设置未保存。 ");}});Check("登录 Windows 时启动",_runtime.Settings.StartWithWindows,v=>{try{_platform?.SetStartup(v);_runtime.UpdateSettings(s=>s.StartWithWindows=v);}catch{ProductDialog.Show("登录时启动","未能修改当前用户的启动项。 ");}});Heading("悬浮窗外观");var slider=new Slider{Minimum=.70,Maximum=.80,Value=_runtime.Settings.Transparency,TickFrequency=.01,IsSnapToTickEnabled=true};slider.ValueChanged+=(_,_)=>_runtime.UpdateSettings(s=>s.Transparency=slider.Value);AutomationProperties.SetName(slider,"透明度");_content.Children.Add(slider);var frost=new ComboBox{ItemsSource=new[]{"关闭","轻薄","适中","浓郁"},SelectedItem=_runtime.Settings.Frost,Margin=new Thickness(0,8,0,8)};frost.SelectionChanged+=(_,_)=>_runtime.UpdateSettings(s=>s.Frost=frost.SelectedItem?.ToString()??"适中");_content.Children.Add(frost);Heading("本地 OpenClaw","持续关照须逐条开启；后台子任务不会批量加入。每小时最多自动恢复 3 次，连续失败保留提醒。支持原生安装及指定 WSL 数据目录。");Field("本地网关地址",_draft.Gateway,v=>_draft.Gateway=v);Field("OpenClaw 用户目录",_draft.Home,v=>_draft.Home=v);Field("WSL 发行版",_draft.Distribution,v=>_draft.Distribution=v);Field("WSL OpenClaw 可执行路径",_draft.Executable,v=>_draft.Executable=v);}
 void Supervision(){Heading("监督范围","按软件选择覆盖当前及后来发现的可核验会话。历史完成须显式启动；OpenClaw 持续关照只恢复明确中断，完成仍提醒验收。");Field("搜索会话、软件或工作区",_search,v=>{_search=v;RenderScope();});var list=new StackPanel();list.Tag="scope";_content.Children.Add(list);RenderScope();_content.Children.Add(MainWindow.Button("启动已完成的选中会话",_runtime.StartCompletedSelected));}
 void RenderScope(){var list=_content.Children.OfType<StackPanel>().FirstOrDefault(x=>Equals(x.Tag,"scope"));if(list==null)return;list.Children.Clear();foreach(var app in AppNames.Known.Where(x=>AppNames.Display(x).Contains(_search,StringComparison.OrdinalIgnoreCase)||string.IsNullOrEmpty(_search))){var b=new CheckBox{Content=AppNames.Display(app)+" 的新鲜会话",IsChecked=_runtime.Settings.SupervisedApps.Contains(app),Foreground=Brushes.White,Margin=new Thickness(0,4,0,4)};b.Click+=(_,_)=>_runtime.ToggleAppSupervision(app);list.Children.Add(b);}foreach(var row in _runtime.Sessions.Where(r=>(r.Title+" "+r.AppName+" "+r.Project).Contains(_search,StringComparison.OrdinalIgnoreCase))){var b=new CheckBox{Content=row.AppName+" · "+SessionText.Primary(row)+" · "+row.Title,IsChecked=_runtime.Settings.SupervisedIds.Contains(row.Id),Foreground=Brushes.White,Margin=new Thickness(0,6,0,3)};b.Click+=(_,_)=>_runtime.ToggleSupervision(row);list.Children.Add(b);if(row.AppId=="openclaw"){var c=new CheckBox{Content="持续关照此 OpenClaw 会话",IsChecked=_runtime.Settings.CareIds.Contains(row.Id),Foreground=Palette.Brush(Palette.Collaboration),Margin=new Thickness(18,2,0,6)};c.Click+=(_,_)=>_runtime.ToggleCare(row);list.Children.Add(c);}}foreach(var id in _runtime.Settings.CareIds.Where(id=>!_runtime.Sessions.Any(r=>r.Id==id)))list.Children.Add(MainWindow.Button("关闭离线会话的持续关照",()=>{_runtime.UpdateSettings(s=>s.CareIds.Remove(id));RenderScope();}));}
 void Prompts(){Heading("提示词草稿","保存后生效；最多 2000 字符，超限保留全文并阻止保存。修改执行规则会取消旧排队。");Field("意外中断提示词",_draft.InterruptText,v=>_draft.InterruptText=v,true);Field("狂暴模式通用恢复提示词",_draft.ResumeText,v=>_draft.ResumeText=v,true);Field("普通续接提示词",_draft.ContinueText,v=>_draft.ContinueText=v,true);Field("特别提示词",_draft.AlternateText,v=>_draft.AlternateText=v,true);Field("特别提示词间隔",_draft.AlternateEveryText,v=>_draft.AlternateEveryText=v);Check("允许限流后恢复",_draft.RateLimitWake,v=>{_draft.RateLimitWake=v;Validate();});Field("限流等待秒数（1–10）",_draft.RateLimitSecondsText,v=>_draft.RateLimitSecondsText=v);Field("限流提示词",_draft.RateLimitText,v=>_draft.RateLimitText=v,true);Heading("软件专属提示词","清空覆盖项后使用软件或通用默认。");foreach(var app in AppNames.Known){var panel=new StackPanel();var outer=_content;var section=new Expander{Header=AppNames.Display(app),Content=panel,Foreground=Brushes.White,Margin=new Thickness(0,4,0,4)};outer.Children.Add(section);var prior=outer.Children.Count;Field(AppNames.Display(app)+" 专属续接",_draft.AppContinue.GetValueOrDefault(app,""),v=>_draft.AppContinue[app]=v,true);Field(AppNames.Display(app)+" 专属恢复",_draft.AppResume.GetValueOrDefault(app,""),v=>_draft.AppResume[app]=v,true);while(outer.Children.Count>prior){var e=outer.Children[prior];outer.Children.RemoveAt(prior);panel.Children.Add(e);}}}
 void Diagnostics(){Heading("本机诊断",_runtime.Diagnostic);_content.Children.Add(MainWindow.Button("查询实际窗口访问",async()=>{if(_platform!=null)ProductDialog.Show("窗口访问查询",await _platform.CheckAccessibilityAsync());}));Heading("当前生效提示词");foreach(var app in AppNames.Known){var prompt=PromptDraft.Recovery(_runtime.Settings,app);Heading(AppNames.Display(app)+" · "+prompt.Source,prompt.Text);}}
 void Validate(){var errors=_draft.ValidationMessages();_validation.Text=string.Join("\n",errors.Take(3));_validation.Foreground=errors.Any(PromptDraft.IsBlocking)?Palette.Brush(Palette.Danger):Palette.Brush(Palette.Muted);_save.IsEnabled=!_draft.HasOverlength&&!errors.Any(PromptDraft.IsBlocking);}
 bool Save(){var notes=new List<string>();var current=SettingsRepository.Clone(_runtime.Settings);if(!_draft.TryApply(current,notes))return false;try{_runtime.UpdateSettings(s=>{s.Popup=current.Popup;s.Sound=current.Sound;s.ResumeText=current.ResumeText;s.InterruptText=current.InterruptText;s.ContinueText=current.ContinueText;s.AlternateText=current.AlternateText;s.AlternateEvery=current.AlternateEvery;s.RateLimitWake=current.RateLimitWake;s.RateLimitSeconds=current.RateLimitSeconds;s.RateLimitText=current.RateLimitText;s.AppContinueTexts=current.AppContinueTexts;s.AppResumeTexts=current.AppResumeTexts;s.OpenClawGateway=current.OpenClawGateway;s.OpenClawHome=current.OpenClawHome;s.WslDistribution=current.WslDistribution;s.WslExecutable=current.WslExecutable;});_draft=PromptDraft.Capture(_runtime.Settings);Validate();return true;}catch{_validation.Text="未能保存本机设置，草稿已保留。";return false;}}
 public bool ConfirmClose(){if(!_draft.HasChanges(_runtime.Settings))return true;return ProductDialog.AskSave("提示词或提醒设置尚未保存。") switch{CloseChoice.Save=>Save(),CloseChoice.Discard=>true,_=>false};}
 void OnClosing(object? sender,CancelEventArgs e){if(!_close&&!ConfirmClose())e.Cancel=true;}
 public void CloseWithoutPrompt(){_close=true;Close();}
}
